#include <list>
#include <algorithm>
#include <iostream>

void demonstrate_list_sort() {
    std::list<int> l = {3, 1, 4, 1, 5};

    // 1. Correct: Use the member function sort()
    l.sort(); 

    // 2. Incorrect/Compiler Error: std::sort requires Random Access Iterators
    // std::sort(l.begin(), l.end()); 

    for (int x : l) {
        std::cout << x << " ";
    }
    std::cout << "\n";
}
